1	package release
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9		"sync"
10		"syscall"
11	)
12	
13	const (
14		stateFileName = "ledger.json"
15		lockFileName  = "ledger.lock"
16		stateVersion  = 1
17	)
18	
19	// Store 是一个本地配方批次台账，数据保存在调用方指定的目录中。
20	// 不同目录互相独立；多个 Store 可以安全并发提交（进程内互斥、进程间文件锁）。
21	type Store struct {
22		dir      string
23		lockFile *os.File
24		mu       sync.Mutex
25		state    *persistedState
26	}
27	
28	// Open 打开（或首次使用）位于 dir 的台账。
29	// 目录不存在时会创建；目录中没有台账文件时得到空台账；
30	// 已有台账文件无法读取、解析，任一配方版本的任一物料每份克数不是正数，
31	// 任一配方版本内同一物料编号出现多次，
32	// 任一批次绑定的配方版本未登记，
33	// 已保存投料的物料编号不属于该批次绑定的配方版本，
34	// 或已保存的投料数量非法（单条不是正数，或同一批次同一物料累计实投
35	// 超过 9223372036854775.807 克）时，返回 ErrCorruptData（可用 errors.Is
36	// 判断），不会当成空台账继续保存，也不会返回可继续使用的台账对象。
37	func Open(dir string) (*Store, error) {
38		if dir == "" {
39			return nil, errors.New("数据位置不能为空")
40		}
41		if err := os.MkdirAll(dir, 0o755); err != nil {
42			return nil, fmt.Errorf("创建数据位置 %q 失败: %w", dir, err)
43		}
44		info, err := os.Stat(dir)
45		if err != nil {
46			return nil, fmt.Errorf("读取数据位置 %q 失败: %w", dir, err)
47		}
48		if !info.IsDir() {
49			return nil, fmt.Errorf("数据位置 %q 不是目录", dir)
50		}
51	
52		lockPath := filepath.Join(dir, lockFileName)
53		lf, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
54		if err != nil {
55			return nil, fmt.Errorf("打开锁文件失败: %w", err)
56		}
57	
58		s := &Store{dir: dir, lockFile: lf}
59		if err := s.load(); err != nil {
60			lf.Close()
61			return nil, err
62		}
63		return s, nil
64	}
65	
66	// Close 释放台账占用的文件锁。
67	func (s *Store) Close() error {
68		s.mu.Lock()
69		defer s.mu.Unlock()
70		if s.lockFile == nil {
71			return nil
72		}
73		err := s.lockFile.Close()
74		s.lockFile = nil
75		return err
76	}
77	
78	func (s *Store) lockExclusive() error {
79		if s.lockFile == nil {
80			return errors.New("台账已关闭")
81		}
82		if err := syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_EX); err != nil {
83			return fmt.Errorf("锁定台账失败: %w", err)
84		}
85		return nil
86	}
87	
88	func (s *Store) lockShared() error {
89		if s.lockFile == nil {
90			return errors.New("台账已关闭")
91		}
92		if err := syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_SH); err != nil {
93			return fmt.Errorf("锁定台账失败: %w", err)
94		}
95		return nil
96	}
97	
98	func (s *Store) unlock() {
99		_ = syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_UN)
100	}
101	
102	func (s *Store) load() error {
103		data, err := os.ReadFile(filepath.Join(s.dir, stateFileName))
104		if err != nil {
105			if os.IsNotExist(err) {
106				s.state = &persistedState{Version: stateVersion, Requests: map[string]*requestRecord{}}
107				return nil
108			}
109			return fmt.Errorf("%w: 读取台账文件失败: %v", ErrCorruptData, err)
110		}
111		if len(data) == 0 {
112			s.state = &persistedState{Version: stateVersion, Requests: map[string]*requestRecord{}}
113			return nil
114		}
115		var st persistedState
116		if err := json.Unmarshal(data, &st); err != nil {
117			return fmt.Errorf("%w: 台账文件解析失败: %v", ErrCorruptData, err)
118		}
119		if st.Version != stateVersion {
120			return fmt.Errorf("%w: 台账版本 %d 不受支持", ErrCorruptData, st.Version)
121		}
122		if err := validateState(&st); err != nil {
123			return err
124		}
125		if st.Requests == nil {
126			st.Requests = map[string]*requestRecord{}
127		}
128		s.state = &st
129		return nil
130	}
131	
132	// validateState 检查台账的引用完整性与数量合法性：
133	//   - 每个配方版本的每种物料，每份克数必须是正数——与登记时的规则一致。
134	//     任一版本（包括尚未被任何批次使用的版本）的任一物料为零或负数，
135	//     整份台账即视为损坏：不能改成最小用量、取绝对值、删除问题物料
136	//     或改用其他版本后继续，其他配方完整或批次数量恰好吻合也不能放行。
137	//   - 同一配方版本的物料列表内，每个物料编号只能出现一次——与登记时的
138	//     规则一致。任一版本（包括尚未被任何批次使用的版本）内同一物料编号
139	//     出现多次，整份台账即视为损坏：不能合并重复项、相加克数、丢弃其中
140	//     一条或由查询者挑一项作为依据，即使两条克数完全相同也不能放行；
141	//     不同版本、不同配方各自使用同一物料编号不受影响。
142	//   - 每个批次记录的配方编号与版本号必须共同指向一个已登记的配方版本。
143	//     任一批次找不到对应版本，整份台账即视为损坏——不能改用同编号的其他版本，
144	//     也不能按名称或物料内容替换，即使其他批次仍然完整也不能放行本次读取。
145	//   - 每条已保存的投料数量必须是正数；同一批次内同一物料的累计实投
146	//     不得超过 maxGramsMilli（9223372036854775.807 克）。任一记录为零或
147	//     负数，或任一物料累计超限，整份台账即视为损坏——负数记录即使能被
148	//     正数抵消回范围内也不接受，超限也不能截断或忽略后继续。
149	//   - 每条已保存投料的物料编号必须属于该批次绑定的配方版本。归属以批次
150	//     实际绑定的版本为准：物料只出现在同编号的其他版本或其他配方中，
151	//     不能作为接受依据；也不能改选版本、补入物料或丢弃问题投料后继续。
152	func validateState(st *persistedState) error {
153		for _, r := range st.Recipes {
154			if r == nil {
155				return fmt.Errorf("%w: 台账中存在空的配方记录", ErrCorruptData)
156			}
157			seen := make(map[string]bool, len(r.Materials))
158			for _, m := range r.Materials {
159				if seen[m.MaterialNo] {
160					return fmt.Errorf("%w: 配方 %q 版本 %q 的物料编号 %q 重复",
161						ErrCorruptData, r.RecipeNo, r.Version, m.MaterialNo)
162				}
163				seen[m.MaterialNo] = true
164				if m.GramsMilli <= 0 {
165					return fmt.Errorf("%w: 配方 %q 版本 %q 物料 %q 的每份克数不是正数",
166						ErrCorruptData, r.RecipeNo, r.Version, m.MaterialNo)
167				}
168			}
169		}
170		for _, b := range st.Batches {
171			if b == nil {
172				return fmt.Errorf("%w: 台账中存在空的批次记录", ErrCorruptData)
173			}
174			r := findRecipe(st, b.RecipeNo, b.RecipeVersion)
175			if r == nil {
176				return fmt.Errorf("%w: 批次 %q 绑定的配方 %q 版本 %q 未登记",
177					ErrCorruptData, b.BatchNo, b.RecipeNo, b.RecipeVersion)
178			}
179			if err := validateFeedings(b, r); err != nil {
180				return err
181			}
182		}
183		return nil
184	}
185	
186	// validateFeedings 检查一个批次内已保存投料的合法性与配方归属。
187	// 归属以批次绑定的配方版本 r 为准：每条投料的物料编号必须在 r 的物料
188	// 列表中，否则整份台账视为损坏。数量方面只判断数量本身是否合法，不判断
189	// 实投是否符合配方：无投料的物料累计为零属正常，不足或超过应投量也不
190	// 在此拒绝。
191	func validateFeedings(b *batchRecord, r *recipeRecord) error {
192		acc := newFeedingAccumulator()
193		for _, f := range b.Feedings {
194			belongs := false
195			for _, m := range r.Materials {
196				if m.MaterialNo == f.MaterialNo {
197					belongs = true
198					break
199				}
200			}
201			if !belongs {
202				return fmt.Errorf("%w: 批次 %q 的第 %d 条投料物料 %q 不属于其绑定的配方 %q 版本 %q",
203					ErrCorruptData, b.BatchNo, f.Seq, f.MaterialNo, b.RecipeNo, b.RecipeVersion)
204			}
205			if f.GramsMilli <= 0 {
206				return fmt.Errorf("%w: 批次 %q 物料 %q 的第 %d 条投料数量不是正数",
207					ErrCorruptData, b.BatchNo, f.MaterialNo, f.Seq)
208			}
209			if !acc.add(f.MaterialNo, f.GramsMilli) {
210				return fmt.Errorf("%w: 批次 %q 物料 %q 的累计实投超出上限 %s 克",
211					ErrCorruptData, b.BatchNo, f.MaterialNo, maxGramsMilli)
212			}
213		}
214		return nil
215	}
216	
217	// persist 先写临时文件再原子改名，并 fsync 目录，保证已提交数据可恢复。
218	func (s *Store) persist(st *persistedState) error {
219		data, err := json.MarshalIndent(st, "", "  ")
220		if err != nil {
221			return err
222		}
223		tmpPath := filepath.Join(s.dir, stateFileName+".tmp")
224		f, err := os.OpenFile(tmpPath, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o644)
225		if err != nil {
226			return err
227		}
228		if _, err := f.Write(data); err != nil {
229			f.Close()
230			return err
231		}
232		if err := f.Sync(); err != nil {
233			f.Close()
234			return err
235		}
236		if err := f.Close(); err != nil {
237			return err
238		}
239		if err := os.Rename(tmpPath, filepath.Join(s.dir, stateFileName)); err != nil {
240			return err
241		}
242		if d, err := os.Open(s.dir); err == nil {
243			_ = d.Sync()
244			_ = d.Close()
245		}
246		return nil
247	}
248	
249	func cloneState(st *persistedState) (*persistedState, error) {
250		data, err := json.Marshal(st)
251		if err != nil {
252			return nil, err
253		}
254		var out persistedState
255		if err := json.Unmarshal(data, &out); err != nil {
256			return nil, err
257		}
258		if out.Requests == nil {
259			out.Requests = map[string]*requestRecord{}
260		}
261		return &out, nil
262	}
263	
264	// write 是所有写入操作的统一入口：
265	//   - reqNo 为空直接报错；
266	//   - 同一 reqNo 且操作与内容完全相同，返回第一次成功的结果（幂等重放）；
267	//   - 同一 reqNo 用于其他操作或不同内容，返回 ErrRequestConflict；
268	//   - apply 在状态副本上执行，返回校验错误时不落盘、不占用请求编号；
269	//   - apply 成功后，状态与请求记录一起原子落盘，再切换到内存状态。
270	func (s *Store) write(reqNo, op string, payload any, apply func(*persistedState) (json.RawMessage, error), out any) error {
271		if reqNo == "" {
272			return errors.New("请求编号不能为空")
273		}
274		s.mu.Lock()
275		defer s.mu.Unlock()
276		if err := s.lockExclusive(); err != nil {
277			return err
278		}
279		defer s.unlock()
280	
281		// 跨进程场景下，其他进程可能已提交新数据；加锁后重新加载，
282		// 确保在最新状态上应用变更，避免用旧快照覆盖其他进程的写入。
283		if err := s.load(); err != nil {
284			return err
285		}
286	
287		payloadRaw, err := json.Marshal(payload)
288		if err != nil {
289			return err
290		}
291		payloadStr := string(payloadRaw)
292	
293		if req, ok := s.state.Requests[reqNo]; ok {
294			if req.Op != op || req.Payload != payloadStr {
295				return fmt.Errorf("%w: 请求编号 %q 已用于操作 %q，不能再用于操作 %q 或不同内容",
296					ErrRequestConflict, reqNo, req.Op, op)
297			}
298			if err := json.Unmarshal(req.Result, out); err != nil {
299				return fmt.Errorf("重放请求 %q 的结果失败: %w", reqNo, err)
300			}
301			return nil
302		}
303	
304		clone, err := cloneState(s.state)
305		if err != nil {
306			return err
307		}
308		result, err := apply(clone)
309		if err != nil {
310			return err
311		}
312		clone.Requests[reqNo] = &requestRecord{Op: op, Payload: payloadStr, Result: result}
313		if err := s.persist(clone); err != nil {
314			return fmt.Errorf("保存台账失败: %w", err)
315		}
316		s.state = clone
317		if err := json.Unmarshal(result, out); err != nil {
318			return fmt.Errorf("解析请求结果失败: %w", err)
319		}
320		return nil
321	}
322	
323	// read 在共享锁下读取当前状态。
324	func (s *Store) read(fn func(*persistedState) error) error {
325		s.mu.Lock()
326		defer s.mu.Unlock()
327		if err := s.lockShared(); err != nil {
328			return err
329		}
330		defer s.unlock()
331		if err := s.load(); err != nil {
332			return err
333		}
334		return fn(s.state)
335	}
336	
337	// 视图构造：每次都从记录全新构造，返回的切片与内部状态完全隔离。
338	
339	func buildRecipeView(r *recipeRecord) *RecipeView {
340		mats := make([]MaterialView, 0, len(r.Materials))
341		for _, m := range r.Materials {
342			mats = append(mats, MaterialView{MaterialNo: m.MaterialNo, Grams: m.GramsMilli.String()})
343		}
344		return &RecipeView{RecipeNo: r.RecipeNo, Version: r.Version, Name: r.Name, Materials: mats}
345	}
346	
347	func buildBatchView(b *batchRecord, r *recipeRecord) (*BatchView, error) {
348		v := &BatchView{
349			BatchNo:         b.BatchNo,
350			RecipeNo:        r.RecipeNo,
351			RecipeVersion:   r.Version,
352			RecipeName:      r.Name,
353			PlannedPortions: b.PlannedPortions,
354			Status:          b.Status,
355			Feedings:        make([]FeedingView, 0, len(b.Feedings)),
356			Materials:       make([]MaterialRequirement, 0, len(r.Materials)),
357		}
358	
359		for _, f := range b.Feedings {
360			v.Feedings = append(v.Feedings, FeedingView{
361				Seq:        f.Seq,
362				MaterialNo: f.MaterialNo,
363				Grams:      f.GramsMilli.String(),
364				Time:       f.Time,
365				Registrar:  f.Registrar,
366			})
367		}
368	
369		// 按物料累计实投量；台账在读取时已通过 validateFeedings 校验，
370		// 这里仍用同一套累计规则防一手整数回绕。
371		acc := newFeedingAccumulator()
372		for _, f := range b.Feedings {
373			if !acc.add(f.MaterialNo, f.GramsMilli) {
374				return nil, fmt.Errorf("%w: 批次 %q 物料 %q 的累计实投超出可表示范围",
375					ErrCorruptData, b.BatchNo, f.MaterialNo)
376			}
377		}
378	
379		// 数量核对按配方物料逐项列出；台账在读取时已通过 validateState 校验，
380		// 这里仍防一手同一版本内物料编号重复，避免返回重复的数量核对项。
381		seen := make(map[string]bool, len(r.Materials))
382		for _, m := range r.Materials {
383			if seen[m.MaterialNo] {
384				return nil, fmt.Errorf("%w: 配方 %q 版本 %q 的物料编号 %q 重复",
385					ErrCorruptData, r.RecipeNo, r.Version, m.MaterialNo)
386			}
387			seen[m.MaterialNo] = true
388			required, err := multiplyPortions(m.GramsMilli, b.PlannedPortions)
389			if err != nil {
390				return nil, fmt.Errorf("批次 %q 数量核对失败: %w", b.BatchNo, err)
391			}
392			act := acc.total(m.MaterialNo)
393			v.Materials = append(v.Materials, MaterialRequirement{
394				MaterialNo:      m.MaterialNo,
395				RequiredGrams:   required.String(),
396				ActualGrams:     act.String(),
397				DifferenceGrams: (act - required).String(),
398			})
399		}
400		return v, nil
401	}
402	
403	func findRecipe(st *persistedState, recipeNo, version string) *recipeRecord {
404		for _, r := range st.Recipes {
405			if r.RecipeNo == recipeNo && r.Version == version {
406				return r
407			}
408		}
409		return nil
410	}
411	
412	func findBatch(st *persistedState, batchNo string) *batchRecord {
413		for _, b := range st.Batches {
414			if b.BatchNo == batchNo {
415				return b
416			}
417		}
418		return nil
419	}
